import * as THREE from 'three/webgpu';
import { texture, uv, vec4, mix } from 'three/tsl';

export default function createNode(config, ctx) {
  const width = 1.6;
  const height = width * (320 / 512);

  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const map = ctx.textureLoader('/prism-assets/chrome/ceramic-grain.map.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const texNode = texture(map, uv());
  const inkTint = vec4(
    THREE.MathUtils.euclideanModulo(0x16 / 255, 1),
    THREE.MathUtils.euclideanModulo(0x16 / 255, 1),
    THREE.MathUtils.euclideanModulo(0x1d / 255, 1),
    1.0
  );

  material.colorNode = mix(texNode, inkTint, 0.06);

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(3.2, -0.3, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && typeof map.dispose === 'function') {
      map.dispose();
    }
  };

  mesh.onBeforeRender = (renderer, scene, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };

  return mesh;
}
